import heapq

def match(orders):
    trades = []
    buy_heap = []   # (-price, arrival, id)
    sell_heap = []  # (price, arrival, id)
    book = {}       # id -> [side, price, qty, arrival, active]
    counter = 0

    def add_to_book(id_, side, price, qty, arrival):
        book[id_] = [side, price, qty, arrival, True]
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, arrival, id_))
        else:
            heapq.heappush(sell_heap, (price, arrival, id_))

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            id_ = order[1]
            if id_ in book and book[id_][4] and book[id_][2] > 0:
                book[id_][4] = False
            continue

        id_ = order[1]
        side = order[2]
        if typ == 'market':
            price = None
            qty = order[3]
        else:
            price = order[3]
            qty = order[4]

        arrival = counter
        counter += 1
        remaining = qty

        heap = sell_heap if side == 'buy' else buy_heap

        while remaining > 0 and heap:
            if side == 'buy':
                top_price, top_arr, top_id = heap[0]
            else:
                neg_price, top_arr, top_id = heap[0]
                top_price = -neg_price

            info = book.get(top_id)
            if info is None or not info[4] or info[2] <= 0:
                heapq.heappop(heap)
                continue

            if typ != 'market':
                if side == 'buy' and top_price > price:
                    break
                if side == 'sell' and top_price < price:
                    break

            trade_qty = min(remaining, info[2])
            if side == 'buy':
                trades.append([id_, top_id, top_price, trade_qty])
            else:
                trades.append([top_id, id_, top_price, trade_qty])

            remaining -= trade_qty
            info[2] -= trade_qty

            if info[2] == 0:
                info[4] = False
                heapq.heappop(heap)

        if typ == 'limit' and remaining > 0:
            add_to_book(id_, side, price, remaining, arrival)

    return trades

